 *
 * **Empty `mapId` means "leave the deployment alone", and that is the
 * default.** Every existing flow keeps working without a click.
 */
interface CustomMap {
  mapId: string;
  newProfileId: string;
  start: Point2D | null;
  goal: Point2D | null;
  /** Which pose the next click on the canvas sets. Flips to `goal` after
   *  the start lands, because that is the order these are chosen in and
   *  making a person toggle a radio between two clicks is friction with
   *  nothing on the other side of it. */
  placing: "start" | "goal";
}

const NO_CUSTOM_MAP: CustomMap = {
  mapId: "",
  newProfileId: "",
  start: null,
  goal: null,
